package com.maxingtime;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;
public class MaxingCalculatorTest
{
    @Test public void targetAndOver99()
    {
        assertEquals(13034431, MaxingCalculator.TARGET_XP);
        assertEquals(0, MaxingCalculator.remaining(200000000));
        assertEquals(0, MaxingCalculator.hours(200000000, 0), 0);
    }
    @Test public void exampleAndUnknownRate()
    {
        assertEquals(8934431, MaxingCalculator.remaining(4100000));
        assertEquals(8934431.0 / 65000, MaxingCalculator.hours(4100000, 65000), 0.000001);
        assertTrue(Double.isNaN(MaxingCalculator.hours(0, 0)));
    }
    @Test public void subtotalDoesNotPretendToBeComplete()
    {
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        Map<Skill, Long> rates = new EnumMap<>(Skill.class);
        xp.put(Skill.AGILITY, 12969431); rates.put(Skill.AGILITY, 65000L);
        xp.put(Skill.MINING, 0); xp.put(Skill.ATTACK, 200000000);
        MaxingCalculator.Summary s = MaxingCalculator.summarize(xp, rates);
        assertEquals(1, s.missing); assertEquals(1, s.completed); assertEquals(1, s.hours, 0);
    }
    @Test public void displayRoundsOnlyAfterSum()
    {
        assertEquals("1h 0m", MaxingCalculator.duration(1));
        assertEquals("0h 1m", MaxingCalculator.duration(0.00001));
        assertEquals("0h 0m", MaxingCalculator.duration(0));
    }
    @Test public void rateParsing()
    {
        assertEquals(0, XpRateStore.parse("")); assertEquals(65000, XpRateStore.parse("65000"));
        for (String bad : new String[]{"-1", "65,000", "NaN", "1.5", "1000000001", "999999999999999999999"})
        {
            try { XpRateStore.parse(bad); fail(bad); } catch (IllegalArgumentException expected) { }
        }
    }
    @org.junit.Test public void passiveSkillsOnlyExcludeTimeAndMissingRates()
    {
        java.util.Map<net.runelite.api.Skill, Integer> xp = new java.util.EnumMap<>(net.runelite.api.Skill.class);
        xp.put(net.runelite.api.Skill.SLAYER, MaxingCalculator.TARGET_XP - 1000000);
        xp.put(net.runelite.api.Skill.MAGIC, MaxingCalculator.TARGET_XP - 500000);
        xp.put(net.runelite.api.Skill.ATTACK, MaxingCalculator.TARGET_XP + 500000);
        java.util.Map<net.runelite.api.Skill, Long> rates = new java.util.EnumMap<>(net.runelite.api.Skill.class);
        rates.put(net.runelite.api.Skill.SLAYER, 50000L);
        MaxingCalculator.Summary summary = MaxingCalculator.summarize(xp, rates,
            java.util.EnumSet.of(net.runelite.api.Skill.MAGIC, net.runelite.api.Skill.ATTACK));
        org.junit.Assert.assertEquals(20, summary.hours, 0.0001);
        org.junit.Assert.assertEquals(0, summary.missing);
        org.junit.Assert.assertEquals(1, summary.ignored);
        org.junit.Assert.assertEquals(1, summary.completed);
        org.junit.Assert.assertEquals(1500000, summary.remaining);
        org.junit.Assert.assertEquals(1, MaxingCalculator.summarize(xp, rates).missing);
    }
}

package com.maxingtime;

import java.awt.Component;
import java.awt.Container;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.*;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

public class MaxingProgressTest
{
    private static Map<Skill, Integer> account(int agilityRemaining)
    {
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values())
        {
            if (!"OVERALL".equals(skill.name())) { xp.put(skill, MaxingCalculator.TARGET_XP); }
        }
        xp.put(Skill.AGILITY, MaxingCalculator.TARGET_XP - agilityRemaining);
        return xp;
    }

    @Test public void millionXpBaselineAdvancesByTenPercent()
    {
        assertEquals(0, MaxingCalculator.progressPercent(1000000, 1000000), 0);
        assertEquals(10, MaxingCalculator.progressPercent(1000000, 900000), 0);
        assertEquals(100, MaxingCalculator.progressPercent(1000000, 0), 0);
        assertEquals(100, MaxingCalculator.progressPercent(0, 0), 0);
        assertEquals(0, MaxingCalculator.progressPercent(100, 200), 0);
    }

    @Test public void overallUsesCappedSkillXpAndNeverTotalXp()
    {
        Map<Skill, Integer> xp = account(1000000);
        double expected = 100.0 * (1 - 1000000.0 / (xp.size() * (long) MaxingCalculator.TARGET_XP));
        assertEquals(expected, MaxingCalculator.overallPercent(xp), 0.0000001);
        xp.put(Skill.ATTACK, 200000000);
        assertEquals(expected, MaxingCalculator.overallPercent(xp), 0.0000001);
        assertEquals(1000000, MaxingCalculator.totalRemaining(xp));
        xp.replaceAll((skill, value) -> 0);
        assertEquals(0, MaxingCalculator.overallPercent(xp), 0);
        xp.replaceAll((skill, value) -> MaxingCalculator.TARGET_XP);
        assertEquals(100, MaxingCalculator.overallPercent(xp), 0);
    }

    @Test public void baselineSerializationAndInvalidData()
    {
        assertEquals(Long.valueOf(1000000), ProgressStore.decode(ProgressStore.encode(1000000)));
        assertEquals(Long.valueOf(0), ProgressStore.decode(ProgressStore.encode(0)));
        assertNull(ProgressStore.decode(null));
        assertNull(ProgressStore.decode("old-skill-list:1000000"));
        assertNull(ProgressStore.decode(ProgressStore.encode(1).replace(":1", ":-1")));
        assertNull(ProgressStore.decode(ProgressStore.encode(1).replace(":1", ":bad")));
    }

    @Test public void buttonAndBarsFollowTheCharacterAndSurviveReopen() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            AtomicReference<String> clicked = new AtomicReference<>();
            MaxingTimePanelTest.MemoryStore rates = new MaxingTimePanelTest.MemoryStore();
            MaxingTimePanel panel = new MaxingTimePanel(rates, clicked::set);
            JButton button = (JButton) find(panel, "Track my maxing progress");
            assertFalse(button.isEnabled());
            panel.update(account(1000000), true, "character-a", null);
            assertTrue(button.isEnabled()); button.doClick(); assertEquals("character-a", clicked.get());
            panel.update(account(900000), true, "character-a", 1000000L);
            JProgressBar tracked = (JProgressBar) find(panel, "Progress since tracking started");
            assertEquals("10.00%", tracked.getString()); assertFalse(button.isEnabled());
            panel.update(account(0), false, null, null);
            assertEquals("Log in to load progress", tracked.getString());
            panel.update(account(500000), true, "character-b", null);
            assertEquals("Not started", tracked.getString()); assertTrue(button.isEnabled());
            MaxingTimePanel reopened = new MaxingTimePanel(rates, clicked::set);
            reopened.update(account(800000), true, "character-a", 1000000L);
            assertEquals("20.00%", ((JProgressBar) find(reopened, "Progress since tracking started")).getString());
            reopened.update(account(1), true, "character-a", 1000000L);
            assertEquals("99.99%", ((JProgressBar) find(reopened, "Progress since tracking started")).getString());
            reopened.update(account(0), true, "character-a", 1000000L);
            assertEquals("100.00%", ((JProgressBar) find(reopened, "Progress since tracking started")).getString());
            assertEquals("100.00%", ((JProgressBar) find(reopened, "Overall maxing progress")).getString());
        });
    }

    @Test public void resetStartsAtCurrentXpWithoutChangingOverall() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            AtomicReference<String> reset = new AtomicReference<>();
            MaxingTimePanel panel = new MaxingTimePanel(new MaxingTimePanelTest.MemoryStore(), key -> { }, reset::set);
            JButton button = (JButton) find(panel, "Reset tracking");
            assertFalse(button.isEnabled());
            panel.update(account(900000), true, "character-a", null);
            assertFalse(button.isEnabled());
            panel.update(account(900000), true, "character-a", 1000000L);
            JProgressBar overall = (JProgressBar) find(panel, "Overall maxing progress");
            String before = overall.getString();
            assertTrue(button.isEnabled()); button.doClick();
            assertEquals("character-a", reset.get());
            // The client-thread action persists the freshly read remaining XP, then sends this snapshot.
            panel.update(account(900000), true, "character-a", 900000L);
            assertEquals("0.00%", ((JProgressBar) find(panel, "Progress since tracking started")).getString());
            assertEquals(before, overall.getString());
            panel.update(account(810000), true, "character-a", 900000L);
            assertEquals("10.00%", ((JProgressBar) find(panel, "Progress since tracking started")).getString());
            panel.update(account(810000), false, null, null);
            assertFalse(button.isEnabled());
        });
    }

    @Test public void searchFiltersSkillsWithoutChangingProgress() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            MaxingTimePanel panel = new MaxingTimePanel(new MaxingTimePanelTest.MemoryStore());
            panel.update(account(1000000), true, "character-a", 2000000L);
            String before = ((JProgressBar) find(panel, "Overall maxing progress")).getString();
            JTextField search = (JTextField) find(panel, "Search skills");
            search.setText("MINING");
            assertFalse(find(panel, "AGILITY").isVisible());
            assertFalse(find(panel, "MINING").isVisible()); // already 99
            search.setText("agil"); assertTrue(find(panel, "AGILITY").isVisible());
            assertEquals(before, ((JProgressBar) find(panel, "Overall maxing progress")).getString());
            search.setText(""); assertTrue(find(panel, "AGILITY").isVisible());
        });
    }

    private static Component find(Container root, String name)
    {
        for (Component child : root.getComponents())
        {
            if (name.equals(child.getName()) || (child instanceof JButton && name.equals(((JButton) child).getText()))) { return child; }
            if (child instanceof Container)
            {
                Component result = find((Container) child, name); if (result != null) { return result; }
            }
        }
        return null;
    }
}

package com.maxingtime;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.runelite.api.Skill;

public final class TrainingMethods
{
    private static final Map<Skill, List<TrainingMethod>> METHODS = load();
    private TrainingMethods() { }
    public static List<TrainingMethod> forSkill(Skill skill) { return METHODS.get(skill); }
    public static TrainingMethod selected(Skill skill, String id)
    {
        return forSkill(skill).stream().filter(m -> m.id.equals(id)).findFirst().orElse(TrainingMethod.CUSTOM);
    }
    private static Map<Skill, List<TrainingMethod>> load()
    {
        Map<Skill, List<TrainingMethod>> result = new EnumMap<>(Skill.class);
        for (Skill skill : Skill.values()) { result.put(skill, new ArrayList<>()); }
        try (InputStream stream = TrainingMethods.class.getResourceAsStream("training-methods.tsv"))
        {
            if (stream == null) { throw new IllegalStateException("Missing training method catalogue"); }
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(stream, StandardCharsets.UTF_8)))
            {
                String line;
                while ((line = reader.readLine()) != null)
                {
                    if (line.startsWith("#") || line.isEmpty()) { continue; }
                    String[] f = line.split("\t", -1);
                    if (f.length != 7) { throw new IllegalStateException("Invalid method row"); }
                    Skill skill;
                    try { skill = Skill.valueOf(f[0]); }
                    catch (IllegalArgumentException absentInOlderApi) { continue; }
                    long rate = XpRateStore.parse(f[3]); int level = Integer.parseInt(f[4]);
                    if (rate == 0 || level < 1 || level > 99 || !f[6].startsWith("https://oldschool.runescape.wiki/w/"))
                    { throw new IllegalStateException("Invalid training benchmark"); }
                    if (result.get(skill).stream().anyMatch(m -> m.id.equals(f[1])))
                    { throw new IllegalStateException("Duplicate method ID"); }
                    result.get(skill).add(new TrainingMethod(f[1], f[2], rate, level, f[5], f[6]));
                }
            }
        }
        catch (IOException ex) { throw new IllegalStateException("Cannot read training methods", ex); }
        result.replaceAll((skill, list) -> {
            list.sort(Comparator.comparingLong(m -> m.rate));
            list.add(0, TrainingMethod.CUSTOM);
            return Collections.unmodifiableList(list);
        });
        return Collections.unmodifiableMap(result);
    }
}

package com.maxingtime;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(name = "Maxing tracker", description = "Estimate training time to 99 and max",
    tags = {"xp", "skills", "max", "planning"})
public class MaxingTimePlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;
    @Inject private XpRateStore rates;
    @Inject private ItemManager itemManager;
    @Inject private ProgressStore progressStore;
    private volatile MaxingTimePanel panel;
    private NavigationButton navigation;

    @Provides MaxingTimeConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(MaxingTimeConfig.class);
    }

    @Override protected void startUp() throws Exception
    {
        // RuneLite starts and stops plugins on the Swing event dispatch thread.
        panel = new MaxingTimePanel(rates, this::startTracking, this::resetTracking);
        itemManager.getImage(ItemID.MAX_CAPE).addTo(panel.getCapeLabel());
        navigation = NavigationButton.builder().tooltip("Maxing tracker").icon(icon())
            .priority(7).panel(panel).build();
        toolbar.addNavigation(navigation);
        clientThread.invokeLater(this::refresh);
    }

    @Override protected void shutDown()
    {
        MaxingTimePanel old = panel;
        panel = null;
        if (navigation != null) { toolbar.removeNavigation(navigation); navigation = null; }
        if (old != null) { SwingUtilities.invokeLater(old::dispose); }
    }

    @Subscribe public void onGameTick(GameTick event) { refresh(); }
    @Subscribe public void onGameStateChanged(GameStateChanged event) { refresh(); }

    private void refresh()
    {
        MaxingTimePanel target = panel;
        if (target == null) { return; }
        Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
        if (loggedIn)
        {
            for (Skill skill : Skill.values())
            {
                if (!"OVERALL".equals(skill.name())) { xp.put(skill, client.getSkillExperience(skill)); }
            }
        }
        String profile = loggedIn ? progressStore.profileFor(client.getAccountHash()) : null;
        Long baseline = progressStore.get(profile);
        SwingUtilities.invokeLater(() -> {
            if (panel == target) { target.update(xp, loggedIn, profile, baseline); }
        });
    }

    private void startTracking(String expectedProfile)
    {
        updateTracking(expectedProfile, false);
    }

    private void resetTracking(String expectedProfile)
    {
        updateTracking(expectedProfile, true);
    }

    private void updateTracking(String expectedProfile, boolean reset)
    {
        MaxingTimePanel expectedPanel = panel;
        clientThread.invokeLater(() -> {
            if (panel != expectedPanel || panel == null || client.getGameState() != GameState.LOGGED_IN) { return; }
            String profile = progressStore.profileFor(client.getAccountHash());
            if (profile == null || !profile.equals(expectedProfile)) { return; }
            Long existing = progressStore.get(profile);
            if (reset ? existing == null : existing != null) { return; }
            // Read at the click action on the client thread, not from an older Swing snapshot.
            long remaining = 0;
            for (Skill skill : Skill.values())
            {
                if (!"OVERALL".equals(skill.name())) { remaining += MaxingCalculator.remaining(client.getSkillExperience(skill)); }
            }
            progressStore.start(profile, remaining);
            refresh();
        });
    }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(236, 183, 74));
        g.fillRect(3, 15, 4, 6); g.fillRect(10, 9, 4, 12); g.fillRect(17, 3, 4, 18);
        g.dispose();
        return image;
    }
}

