        private void select(int index)
        {
            if (disposed || index < 0) { return; }
            store.setMethod(skill, methods.get(index).id);
            invalid = false; error.setVisible(false);
            // Force a refresh even if the custom input still owns focus during selection.
            input.setText(store.effectiveRate(skill) == 0 ? "" : Long.toString(store.effectiveRate(skill)));
            render();
        }

        private void saveCustom()
        {
            if (disposed || !TrainingMethods.selected(skill, store.getMethod(skill)).isCustom()) { return; }
            try
            {
                store.set(skill, XpRateStore.parse(input.getText()));
                invalid = false; error.setVisible(false); render();
            }
            catch (IllegalArgumentException ex)
            {
                invalid = true; error.setText("Use 0–1000000000, digits only"); error.setVisible(true);
                revalidate();
            }
        }

        private void sync(long rate)
        {
            TrainingMethod method = TrainingMethods.selected(skill, store.getMethod(skill));
            syncing = true;
            passive.setSelected(store.isPassive(skill));
            choice.setSelectedItem(method);
            methodName.setText(html(method.name));
            syncing = false;
            input.setEditable(method.isCustom());
            editor.setVisible(method.isCustom()); rateLabel.setVisible(!method.isCustom());
            rateLabel.setText(numbers.format(rate) + " XP/hr");
            choice.setToolTipText(html(method.name + "\n" + method.notes + "\nRight-click to open Wiki source."));
            if ((!input.hasFocus() && !invalid) || !method.isCustom())
            {
                String text = rate == 0 ? "" : Long.toString(rate);
                if (!input.getText().equals(text)) { input.setText(text); }
            }
            wiki.setVisible(!method.isCustom());
            wiki.setToolTipText(html(method.notes + "\nSource: OSRS Wiki. Snapshot checked 2026-09-06."));
            methodName.setToolTipText(html(method.notes));
        }
    }
}

package com.maxingtime;

import java.util.Arrays;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;

/** Baseline is stored in the explicit character/game-mode profile, not a shared rate profile. */
public class ProgressStore
{
    private static final String KEY = "maxingProgressStartV1";
    private static final String SKILLS = Arrays.stream(Skill.values())
        .filter(s -> !"OVERALL".equals(s.name())).map(Skill::name).sorted().collect(Collectors.joining(","));
    @Inject private ConfigManager configManager;

    public String profileFor(long accountHash)
    {
        if (accountHash == -1) { return null; }
        String key = configManager.getRSProfileKey();
        if (key == null) { return null; }
        for (RuneScapeProfile profile : configManager.getRSProfiles())
        {
            if (key.equals(profile.getKey()) && accountHash == profile.getAccountHash()) { return key; }
        }
        return null;
    }

    public Long get(String profile)
    {
        return profile == null ? null : decode(configManager.getConfiguration(MaxingTimeConfig.GROUP, profile, KEY));
    }

    public void start(String profile, long remaining)
    {
        if (profile == null) { throw new IllegalArgumentException("Character not ready"); }
        configManager.setConfiguration(MaxingTimeConfig.GROUP, profile, KEY, encode(remaining));
    }

    static String encode(long remaining)
    {
        if (remaining < 0 || remaining > (long) Skill.values().length * MaxingCalculator.TARGET_XP)
        { throw new IllegalArgumentException("Invalid baseline"); }
        return SKILLS + ":" + remaining;
    }

    static Long decode(String value)
    {
        if (value == null || !value.startsWith(SKILLS + ":")) { return null; }
        try
        {
            long result = Long.parseLong(value.substring(SKILLS.length() + 1));
            encode(result);
            return result;
        }
        catch (IllegalArgumentException invalid) { return null; }
    }
}

package com.maxingtime;

import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;

/** Rates belong to the selected RuneLite configuration profile (shared across characters). */
public class XpRateStore
{
    @Inject private ConfigManager configManager;
    public static final long MAX_RATE = 1_000_000_000L;

    private String key(Skill skill) { return "rate_" + skill.name().toLowerCase(Locale.ROOT); }

    public long get(Skill skill)
    {
        try { return parse(configManager.getConfiguration(MaxingTimeConfig.GROUP, key(skill))); }
        catch (IllegalArgumentException ex) { return 0; }
    }

    public void set(Skill skill, long rate)
    {
        if (rate < 0 || rate > MAX_RATE) { throw new IllegalArgumentException("Invalid XP/hr"); }
        configManager.setConfiguration(MaxingTimeConfig.GROUP, key(skill), rate);
    }

    public String getMethod(Skill skill)
    {
        String value = configManager.getConfiguration(MaxingTimeConfig.GROUP, "method_" + key(skill));
        return value == null ? "custom" : value;
    }

    public void setMethod(Skill skill, String method)
    {
        configManager.setConfiguration(MaxingTimeConfig.GROUP, "method_" + key(skill), method);
    }

    public boolean isPassive(Skill skill)
    {
        return Boolean.parseBoolean(configManager.getConfiguration(MaxingTimeConfig.GROUP, "passive_" + key(skill)));
    }

    public void setPassive(Skill skill, boolean passive)
    {
        configManager.setConfiguration(MaxingTimeConfig.GROUP, "passive_" + key(skill), passive);
    }

    public long effectiveRate(Skill skill)
    {
        TrainingMethod method = TrainingMethods.selected(skill, getMethod(skill));
        return method.isCustom() ? get(skill) : method.rate;
    }

    public static long parse(String text)
    {
        if (text == null || text.trim().isEmpty()) { return 0; }
        String value = text.trim();
        if (!value.matches("[0-9]+")) { throw new IllegalArgumentException("Use whole numbers without separators"); }
        long rate = Long.parseLong(value);
        if (rate > MAX_RATE) { throw new IllegalArgumentException("XP/hr is too large"); }
        return rate;
    }
}

